package com.autocare.platform.order;
import com.autocare.platform.common.ApiResponse;
import com.autocare.platform.common.write.WriteIntegrityService;
import com.autocare.platform.gateway.identity.OperatorActor;
import com.autocare.platform.vehicle.VehicleOwner;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.http.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.util.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController public class CommunityQuestionController {
 private final ObjectProvider<CommunityQuestionPolicies> policies;private final ObjectProvider<CommunityQuestions> cases;
 public CommunityQuestionController(ObjectProvider<CommunityQuestionPolicies> policies,ObjectProvider<CommunityQuestions> cases){this.policies=policies;this.cases=cases;}
 private <T>T configured(ObjectProvider<T> p){var s=p.getIfAvailable();if(s==null)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"私有问答数据库尚未配置");return s;}
 private ResponseEntity<?> ok(Object n){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(ApiResponse.success(n));}
 private ResponseEntity<?> receipt(Object n){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(n);}
 private int page(MultiValueMap<String,String> q){return InvitationController.query(q,true);}
 private void write(long id,String key,MultiValueMap<String,String> q){if(id!=0)com.autocare.platform.service.ServiceCatalog.validateId(id);InvitationController.query(q,false);WriteIntegrityService.normalizeKey(key);}
 @GetMapping("/api/owner/community/questions/context") public ResponseEntity<?> context(@AuthenticationPrincipal Jwt j,@RequestParam MultiValueMap<String,String> q){var a=VehicleOwner.from(j);InvitationController.query(q,false);return ok(configured(cases).context(a));}
 @GetMapping("/api/owner/community/questions/cases") public ResponseEntity<?> ownerList(@AuthenticationPrincipal Jwt j,@RequestParam MultiValueMap<String,String> q){var a=VehicleOwner.from(j);return ok(configured(cases).list(a,false,page(q)));}
 @PostMapping(value="/api/owner/community/questions/cases",consumes="application/json") public ResponseEntity<?> create(@AuthenticationPrincipal Jwt j,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody String raw,@RequestParam MultiValueMap<String,String> q){var a=VehicleOwner.from(j);write(0,key,q);return receipt(configured(cases).create(a,key,CommunityQuestions.input(raw,"create")));}
 @GetMapping("/api/owner/community/questions/cases/{id}") public ResponseEntity<?> ownerDetail(@AuthenticationPrincipal Jwt j,@PathVariable long id,@RequestParam MultiValueMap<String,String> q){var a=VehicleOwner.from(j);com.autocare.platform.service.ServiceCatalog.validateId(id);return ok(configured(cases).detail(a,id,page(q)));}
 @PostMapping(value="/api/owner/community/questions/cases/{id}/message",consumes="application/json") public ResponseEntity<?> message(@AuthenticationPrincipal Jwt j,@PathVariable long id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody String raw,@RequestParam MultiValueMap<String,String> q){var a=VehicleOwner.from(j);writeId(id,key,q);return receipt(configured(cases).write(a,id,"message",key,CommunityQuestions.input(raw,"message")));}
 @PostMapping(value="/api/owner/community/questions/cases/{id}/close",consumes="application/json") public ResponseEntity<?> ownerClose(@AuthenticationPrincipal Jwt j,@PathVariable long id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody String raw,@RequestParam MultiValueMap<String,String> q){var a=VehicleOwner.from(j);writeId(id,key,q);return receipt(configured(cases).write(a,id,"close",key,CommunityQuestions.input(raw,"close")));}
 private void writeId(long id,String key,MultiValueMap<String,String> q){com.autocare.platform.service.ServiceCatalog.validateId(id);write(id,key,q);}
 @GetMapping("/api/admin/community/questions/policies") public ResponseEntity<?> policies(@AuthenticationPrincipal Jwt j,@RequestParam MultiValueMap<String,String> q){var a=OperatorActor.from(j);return ok(configured(policies).list(a,page(q)));}
 @PostMapping(value="/api/admin/community/questions/policies",consumes="application/json") public ResponseEntity<?> createPolicy(@AuthenticationPrincipal Jwt j,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody String raw,@RequestParam MultiValueMap<String,String> q){var a=OperatorActor.from(j);write(0,key,q);return receipt(configured(policies).save(a,null,key,CommunityQuestionPolicies.input(raw,false)));}
 @PutMapping(value="/api/admin/community/questions/policies/{id}",consumes="application/json") public ResponseEntity<?> updatePolicy(@AuthenticationPrincipal Jwt j,@PathVariable long id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody String raw,@RequestParam MultiValueMap<String,String> q){var a=OperatorActor.from(j);writeId(id,key,q);return receipt(configured(policies).save(a,id,key,CommunityQuestionPolicies.input(raw,true)));}
 @PutMapping(value="/api/admin/community/questions/policies/{id}/status",consumes="application/json") public ResponseEntity<?> status(@AuthenticationPrincipal Jwt j,@PathVariable long id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody String raw,@RequestParam MultiValueMap<String,String> q){var a=OperatorActor.from(j);writeId(id,key,q);return receipt(configured(policies).status(a,id,key,CouponInput.status(raw)));}
 @GetMapping("/api/admin/community/questions/handlers") public ResponseEntity<?> handlers(@AuthenticationPrincipal Jwt j,@RequestParam MultiValueMap<String,String> q){var a=OperatorActor.from(j);return ok(configured(policies).handlers(a,page(q)));}
 @GetMapping("/api/admin/community/questions/cases") public ResponseEntity<?> adminList(@AuthenticationPrincipal Jwt j,@RequestParam MultiValueMap<String,String> q){var a=OperatorActor.from(j);var rest=new LinkedMultiValueMap<String,String>(q);boolean queue=false;if(rest.containsKey("scope")){if(rest.get("scope").size()!=1||!java.util.Set.of("mine","queue").contains(rest.getFirst("scope")))throw ReservationInput.bad();queue="queue".equals(rest.remove("scope").get(0));}return ok(configured(cases).list(a,queue,page(rest)));}
 @GetMapping("/api/admin/community/questions/cases/{id}") public ResponseEntity<?> adminDetail(@AuthenticationPrincipal Jwt j,@PathVariable long id,@RequestParam MultiValueMap<String,String> q){var a=OperatorActor.from(j);com.autocare.platform.service.ServiceCatalog.validateId(id);return ok(configured(cases).detail(a,id,page(q)));}
 @PutMapping(value="/api/admin/community/questions/cases/{id}/assignment",consumes="application/json") public ResponseEntity<?> assign(@AuthenticationPrincipal Jwt j,@PathVariable long id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody String raw,@RequestParam MultiValueMap<String,String> q){var a=OperatorActor.from(j);writeId(id,key,q);return receipt(configured(cases).assign(a,id,key,CommunityQuestions.input(raw,"assign")));}
 @PostMapping(value="/api/admin/community/questions/cases/{id}/reply",consumes="application/json") public ResponseEntity<?> reply(@AuthenticationPrincipal Jwt j,@PathVariable long id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody String raw,@RequestParam MultiValueMap<String,String> q){var a=OperatorActor.from(j);writeId(id,key,q);return receipt(configured(cases).write(a,id,"reply",key,CommunityQuestions.input(raw,"reply")));}
 @PostMapping(value="/api/admin/community/questions/cases/{id}/close",consumes="application/json") public ResponseEntity<?> adminClose(@AuthenticationPrincipal Jwt j,@PathVariable long id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody String raw,@RequestParam MultiValueMap<String,String> q){var a=OperatorActor.from(j);writeId(id,key,q);return receipt(configured(cases).write(a,id,"close",key,CommunityQuestions.input(raw,"close")));}
 @ExceptionHandler(ResponseStatusException.class) ResponseEntity<?> error(ResponseStatusException e){int s=e.getStatusCode().value();return ResponseEntity.status(s).cacheControl(CacheControl.noStore()).body(ApiResponse.error(s==400?40001:s*100,e.getReason()));}
 @ExceptionHandler(org.springframework.dao.DataAccessException.class) ResponseEntity<?> unavailable(){return ResponseEntity.status(503).cacheControl(CacheControl.noStore()).body(ApiResponse.error(50300,"私有问答资料暂不可用，请重试原操作"));}
}
